using namespace std;

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    int remove = n - k;
    string st;  // monotonic stack of digits
    for (int i = 0; i < n; i++) {
        int d;
        scanf("%d", &d);
        char c = '0' + d;
        while (remove && !st.empty() && st.back() < c) { st.pop_back(); remove--; }
        st.push_back(c);
    }
    st.resize(k);
    size_t first = st.find_first_not_of('0');
    puts(first == string::npos ? "0" : st.c_str() + first);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); int k = (int) st.nval;
        int remove = n - k;
        StringBuilder stack = new StringBuilder(); // monotonic stack of digits
        for (int i = 0; i < n; i++) {
            st.nextToken();
            char c = (char) ('0' + (int) st.nval);
            while (remove > 0 && stack.length() > 0 && stack.charAt(stack.length() - 1) < c) {
                stack.setLength(stack.length() - 1);
                remove--;
            }
            stack.append(c);
        }
        stack.setLength(k);
        int first = 0;
        while (first < k && stack.charAt(first) == '0') first++;
        System.out.println(first == k ? "0" : stack.substring(first));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var n, k int
	fmt.Fscan(in, &n, &k)
	remove := n - k
	stack := make([]byte, 0, n) // monotonic stack of digits
	for i := 0; i < n; i++ {
		var d int
		fmt.Fscan(in, &d)
		c := byte('0' + d)
		for remove > 0 && len(stack) > 0 && stack[len(stack)-1] < c {
			stack = stack[:len(stack)-1]
			remove--
		}
		stack = append(stack, c)
	}
	res := strings.TrimLeft(string(stack[:k]), "0")
	if res == "" {
		res = "0"
	}
	fmt.Println(res)
}
